<article class="product-card"><a class="product-photo" href="{{ route('product', $product->id) }}"><span class="material-image {{ $product->image_path }}" role="img" aria-label="Ảnh minh họa {{ $product->name }}"></span></a><div class="product-info"><a href="{{ route('product', $product->id) }}"><h3>{{ $product->name }}</h3></a><p class="spec">{{ $product->specification }}</p><div class="product-price"><div class="product-price-value"><strong>{{ number_format($product->price, 0, ',', '.') }}đ</strong><span>/ {{ $product->unit }}</span></div><p class="product-stock {{ $product->has_stock ? 'is-available' : 'is-unavailable' }}">{{ $product->has_stock ? 'Tồn kho: '.rtrim(rtrim(number_format((float) $product->available_stock, 3, ',', '.'), '0'), ',').' '.$product->unit : 'Hết hàng' }}</p></div><form action="{{ route('cart.add') }}" method="post">@csrf<input type="hidden" name="product_id" value="{{ $product->id }}"><input type="hidden" name="quantity" value="1"><button class="add-line" type="submit">Thêm vào giỏ</button></form></div></article>
